package os.aios.core;
import android.app.Instrumentation;
import android.os.*;
import android.content.*;
import org.json.*;
import java.io.*;
import java.nio.*;
import java.nio.file.Files;
import os.aios.core.embedding.*;
import os.aios.core.indexing.*;
import os.aios.core.search.SearchCoordinator;
import os.aios.core.workspace.WorkspaceStore;
import os.aios.core.automation.ContinuousPolicy;

/** Isolated fixture DB and read-only provider checks. Never resets user data. */
public final class SearchAcceptance extends Instrumentation {
    private int passed,failed;private final JSONArray checks=new JSONArray();private Bundle options;
    public void onCreate(Bundle args){super.onCreate(args);options=args;start();}
    interface Check{void run()throws Exception;}
    void check(String name,Check test){try{test.run();passed++;checks.put(new JSONObject().put("name",name).put("state","passed"));}catch(Throwable e){failed++;try{checks.put(new JSONObject().put("name",name).put("state","failed").put("error",e.toString()));}catch(Exception ignored){}}}
    void require(boolean value,String reason){if(!value)throw new AssertionError(reason);}
    public void onStart(){Context c=getTargetContext();
        if(options==null||!options.getString("inventory_only","false").equals("true")){
        check("night_boundary",()->{require(ContinuousPolicy.inWindow(0,0,360),"midnight");require(!ContinuousPolicy.inWindow(360,0,360),"end exclusive");require(ContinuousPolicy.inWindow(60,1320,360),"cross midnight");require(!ContinuousPolicy.inWindow(600,1320,360),"day");});
        check("face_zero_vs_unknown",()->{require(FaceDecoder.decode(new float[2304*16],new float[2304],192,192).length()==0,"zero detector result");});
        check("face_coordinate_mapping",()->{float[] boxes=new float[2304*16],scores=new float[2304];java.util.Arrays.fill(scores,-100);int i=24*48+24;scores[i]=10;boxes[i*16+2]=40;boxes[i*16+3]=40;JSONArray faces=FaceDecoder.decode(boxes,scores,384,192);require(faces.length()==1,"one face");require(faces.getJSONObject(0).getDouble("right")<=384,"bounds");});
        check("sqlite_vec_real_knn",()->{String space="eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee";try(VectorIndex index=new VectorIndex(c,space)){float[] x=new float[512],y=new float[512];x[0]=1;y[1]=1;index.put(1,x);index.put(2,y);JSONArray hits=index.nearest(x,2);require(hits.length()==2&&hits.getJSONObject(0).getLong("id")==1,"nearest identity");index.remove(1);require(index.nearest(x,2).length()==1,"delete");index.remove(2);}});
        check("generation_atomic_publish_and_isolation",()->{
            String dbName="search-generation-acceptance.db",a="dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd",b="cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc";c.deleteDatabase(dbName);
            try(PhotoIndexStore store=new PhotoIndexStore(c,dbName)){
                store.prepare(new JSONObject().put("space_id",a));JSONArray sources=new JSONArray();for(int i=1;i<=2;i++)sources.put(new JSONObject().put("id",Integer.toString(i)).put("source_version","v1").put("database_version","fixture").put("fields",new JSONObject().put("volume_name","fixture")));
                store.discover(sources,false,2);require(!store.coverageComplete(),"Pending rows reported complete");JSONArray rows=store.pending(a,2);float[] x=new float[512];x[0]=1;
                try(VectorIndex old=new VectorIndex(c,a,0)){for(int i=0;i<rows.length();i++){long id=rows.getJSONObject(i).getLong("id");old.put(id,x);store.publish(id,"v1","embedding","ready",null);store.publish(id,"v1","face","ready",new JSONObject().put("detected_count",0));store.publish(id,"v1","exif","no_metadata",new JSONObject());}require(old.size()==2,"old generation vectors");require(store.coverageComplete(),"Complete coverage missing");}
                long atomicId=rows.getJSONObject(0).getLong("id");store.getWritableDatabase().execSQL("CREATE TRIGGER reject_test_snapshot BEFORE INSERT ON photo_snapshots BEGIN SELECT RAISE(ABORT,'fixture_abort'); END");boolean rolledBack=false;try{store.publish(atomicId,"v1","face","failed",new JSONObject().put("error","fixture"));}catch(android.database.sqlite.SQLiteException expected){rolledBack=true;}finally{store.getWritableDatabase().execSQL("DROP TRIGGER reject_test_snapshot");}require(rolledBack&&store.photo(atomicId).getString("face_state").equals("ready")&&store.photo(atomicId,0).getString("face_state").equals("ready"),"Photo and snapshot must commit atomically");
                store.prepare(new JSONObject().put("space_id",b));long next=store.generationFor(b);require(next>0&&store.activeGeneration().getString("space_id").equals(a),"Staging replaced active");rows=store.pending(b,2);long first=rows.getJSONObject(0).getLong("id");require(store.photo(first,0).getString("space_id").equals(a),"Old snapshot overwritten");
                try(VectorIndex target=new VectorIndex(c,b,next)){require(target.size()==0,"Spaces mixed");require(!store.publishGeneration(b,0),"Partial generation published");for(int i=0;i<rows.length();i++){long id=rows.getJSONObject(i).getLong("id");target.put(id,x);store.publish(id,"v1","embedding","ready",null);store.publish(id,"v1","face","ready",new JSONObject().put("detected_count",0));}boolean rejected=false;try{store.publishGeneration(b,1);}catch(IllegalStateException expected){rejected=true;}require(rejected,"Incomplete vectors published");require(store.activeGeneration().getLong("id")==0,"Failure changed active");require(store.publishGeneration(b,target.size()),"Complete generation not published");require(store.activeGeneration().getLong("id")==next,"Active generation mismatch");require(store.metadataFor(sources.getJSONObject(0)).getString("space_id").equals(b),"Metadata not switched");store.invalidate(first);require(store.photo(first,0)==null&&store.photo(first,next)==null,"Invisible snapshot exposed");for(int i=0;i<rows.length();i++)target.remove(rows.getJSONObject(i).getLong("id"));}
                try(VectorIndex old=new VectorIndex(c,a,0)){require(old.size()==2,"Staging changed old vectors");for(int i=0;i<rows.length();i++)old.remove(rows.getJSONObject(i).getLong("id"));}
            }finally{c.deleteDatabase(dbName);}
        });
        check("gpu_validation_rejects_changed_rom",()->{JSONObject evidence=new JSONObject(Files.readString(new File(c.getFilesDir(),"search-models/validated.json").toPath()));JSONObject actual=new JSONObject().put("fingerprint",android.os.Build.FINGERPRINT);for(String prop:new String[]{"ro.system.build.version.incremental","ro.lineage.version","ro.vendor.build.fingerprint"})actual.put(prop,Class.forName("android.os.SystemProperties").getMethod("get",String.class).invoke(null,prop));require(ModelRegistry.matchesRom(evidence),"Current ROM evidence mismatch: "+actual);evidence.put("system_incremental","different-system-build");require(!ModelRegistry.matchesRom(evidence),"Stale ROM evidence accepted");});
        check("immutable_model_profile_pair",()->{ModelRegistry current=new ModelRegistry(c);current.pinCurrent();String space=current.manifest().getString("space_id");ModelRegistry pinned=new ModelRegistry(c,space);require(!pinned.directory().equals(current.directory()),"Profile not archived");for(String role:new String[]{"image","text","face"})require(pinned.validated(role),"Pinned model validation");require(java.util.Arrays.equals(new ClipTokenizer(c).encode("a bicycle"),new ClipTokenizer(c,space).encode("a bicycle")),"Paired tokenizer");});
        try(WorkspaceStore db=new WorkspaceStore(c,"search-acceptance.db")){
            SearchCoordinator search=new SearchCoordinator(c,db);
            check("legacy_recall_compatible",()->require(db.call("recall.query",new JSONObject().put("query","fixture")).getJSONObject("data").has("items"),"v1 contract"));
            check("sources_contract",()->require(search.call("recall.sources",new JSONObject()).getJSONObject("data").getJSONArray("items").length()>=8,"sources"));
            check("unknown_filter_rejected",()->{try{search.call("recall.query",new JSONObject().put("version",2).put("filters",new JSONObject().put("unknown",true)));throw new AssertionError("Accepted unknown filter");}catch(IllegalArgumentException expected){}});
            check("skill_excluded",()->{try{search.call("recall.query",new JSONObject().put("version",2).put("sources",new JSONArray().put("skills")));throw new AssertionError("Skill searchable");}catch(IllegalArgumentException expected){}});
            check("expired_cursor_rejected",()->{try{search.call("recall.query",new JSONObject().put("version",2).put("cursor","invalid"));throw new AssertionError("Invalid cursor accepted");}catch(IllegalArgumentException expected){}});
            check("local_task_query",()->{JSONObject created=db.call("task.create",new JSONObject().put("title","检索验收自行车").put("content_md","fixture sentinel 4817").put("status","note")).getJSONObject("data");JSONObject result=search.call("recall.query",new JSONObject().put("version",2).put("query","4817").put("sources",new JSONArray().put("tasks"))).getJSONObject("data");require(result.getJSONArray("items").length()>0,"task body match");});
            check("literal_sql_wildcard",()->{JSONObject result=search.call("recall.query",new JSONObject().put("version",2).put("query","%_\\").put("sources",new JSONArray().put("tasks"))).getJSONObject("data");require(result.getJSONArray("items").length()==0,"wildcard escaped");});
            for(String source:new String[]{"photos","sms","calls","contacts","calendar"})check("provider_"+source,()->{JSONObject result=search.call("recall.query",new JSONObject().put("version",2).put("query","").put("limit",2).put("sources",new JSONArray().put(source))).getJSONObject("data");JSONArray states=result.getJSONArray("sources");require(states.length()==1,"source status");require(!states.getJSONObject(0).optString("state").equals("unavailable"),"provider unavailable");require(result.getJSONArray("items").length()<=2,"result bound");});
        }catch(Exception e){check("fixture_setup",()->{throw e;});}
        check("exif_original_time_and_unknown_offset",()->{
            File file=File.createTempFile("exif-fixture-",".jpg",c.getCacheDir());try{
                android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(20,10,android.graphics.Bitmap.Config.ARGB_8888);try(FileOutputStream out=new FileOutputStream(file)){bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,95,out);}bitmap.recycle();
                androidx.exifinterface.media.ExifInterface exif=new androidx.exifinterface.media.ExifInterface(file);exif.setAttribute(androidx.exifinterface.media.ExifInterface.TAG_MODEL,"FixtureCamera");exif.setAttribute(androidx.exifinterface.media.ExifInterface.TAG_DATETIME_ORIGINAL,"2026:10:25 12:00:00");exif.saveAttributes();
                try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY)){JSONObject data=PhotoExif.extract(fd,false);require(data.getJSONObject("fields").getBoolean("offset_unknown"),"unknown offset");require(!data.getJSONObject("fields").has("taken_at_ms"),"must not invent timezone");require(data.getJSONObject("fields").getString("camera_model").equals("FixtureCamera"),"camera model");}
            }finally{file.delete();}
        });
        check("photo_preview_uses_authorized_fd",()->{
            JSONObject response=new os.aios.runtime.DeviceSearchClient(c).call("query",new JSONObject().put("source","photos").put("limit",1));JSONArray rows=response.getJSONArray("items");if(rows.length()==0)return;JSONObject photo=rows.getJSONObject(0);
            android.net.Uri uri=new android.net.Uri.Builder().scheme("content").authority("os.aios.core.runtime").appendPath("photo").appendPath(photo.getString("id")).appendQueryParameter("version",photo.getString("source_version")).build();
            try(ParcelFileDescriptor fd=c.getContentResolver().openFileDescriptor(uri,"r")){require(fd!=null&&fd.getStatSize()>0,"photo proxy readable");}
        });
        check("screenshot_no_exif",()->{
            File file=File.createTempFile("no-exif-fixture-",".png",c.getCacheDir());try{android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(20,10,android.graphics.Bitmap.Config.ARGB_8888);try(FileOutputStream out=new FileOutputStream(file)){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY)){require(PhotoExif.extract(fd,false).getString("state").equals("no_metadata"),"PNG without EXIF must be no_metadata");}}finally{file.delete();}
        });
        check("dag_pause_resume_rejects_old_lease",()->{
            os.aios.runtime.CoreRuntimeClient core=new os.aios.runtime.CoreRuntimeClient(c);String id="search-test-"+java.util.UUID.randomUUID(),grant=id+"-grant";
            core.call("automation","authorization.put",new JSONObject().put("id",grant).put("subject","search-acceptance").put("approved_version",1).put("capabilities",new JSONArray().put("scheduler.execute")).put("resources",new JSONArray()));
            core.call("automation","graph.put",new JSONObject().put("id",id).put("nodes",new JSONArray().put(new JSONObject().put("id","step").put("kind","action"))));
            JSONObject run=core.call("automation","run.start",new JSONObject().put("graph_id",id).put("occurrence","fixture").put("authorization_id",grant));String rid=run.getString("id");
            try{JSONObject lease=core.call("automation","node.claim",new JSONObject().put("run_id",rid).put("node_id","step").put("owner",id));
                core.call("automation","run.pause",new JSONObject().put("id",rid));core.call("automation","run.resume",new JSONObject().put("id",rid));
                boolean denied=false;try{core.call("automation","node.finish",new JSONObject().put("run_id",rid).put("node_id","step").put("owner",id).put("generation",lease.getInt("generation")).put("state","succeeded"));}catch(Exception expected){denied=true;}require(denied,"Old lease accepted after pause/resume");
            }finally{try{core.call("automation","run.cancel",new JSONObject().put("id",rid));}catch(Exception ignored){}core.call("automation","authorization.revoke",new JSONObject().put("id",grant));}
        });
        check("tokenizer_matches_paired_model",()->{JSONArray golden;try(InputStream fixture=getContext().getAssets().open("tokenizer-golden.json")){golden=new JSONArray(new String(fixture.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}ClipTokenizer tokenizer=new ClipTokenizer(c);for(int i=0;i<golden.length();i++){JSONObject item=golden.getJSONObject(i);int[] tokens=tokenizer.encode(item.getString("query"));JSONArray expected=item.getJSONArray("tokens");for(int k=0;k<tokens.length;k++)require(tokens[k]==expected.getInt(k),"token mismatch");}});
        if(options!=null&&options.getString("gpu","false").equals("true")){
            check("gpu_face_small_in_frame",()->{FloatBuffer source=ByteBuffer.wrap(Files.readAllBytes(new File(c.getFilesDir(),"search-models/face-input.bin").toPath())).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();float[] original=new float[source.remaining()];source.get(original);float[] small=new float[192*192*3];java.util.Arrays.fill(small,-1f);for(int y=0;y<96;y++)for(int x=0;x<96;x++)for(int channel=0;channel<3;channel++)small[((y+48)*192+x+48)*3+channel]=original[((y*2)*192+x*2)*3+channel];Bundle result=new EmbeddingClient(c).run("face",small,null,false);float[] a=result.getFloatArray("output_0"),b=result.getFloatArray("output_1");JSONArray faces=FaceDecoder.decode(a.length>b.length?a:b,a.length>b.length?b:a,192,192);require(faces.length()>0,"Half-scale public portrait face missing");JSONObject face=faces.getJSONObject(0);double center=(face.getDouble("left")+face.getDouble("right"))/2;require(center>=48&&center<=144,"Small face mapped outside inset");});
            if(options.getString("rider","false").equals("true"))check("gpu_rider_recalled_by_bicycle",()->{
                File root=new File(c.getFilesDir(),"search-models");JSONObject fixture=new JSONObject(Files.readString(new File(root,"rider-fixture.json").toPath()));require(fixture.getString("space_id").equals(new ModelRegistry(c).manifest().getString("space_id")),"Fixture vector space mismatch");File picture=new File(root,"rider.jpg"),reference=new File(root,"fixture-gpu-vectors.bin");require(ModelRegistry.sha256(picture).equals(fixture.getString("rider_sha256"))&&ModelRegistry.sha256(reference).equals(fixture.getString("vectors_sha256")),"Fixture hash mismatch");android.graphics.Bitmap bitmap=android.graphics.ImageDecoder.decodeBitmap(android.graphics.ImageDecoder.createSource(picture),(decoder,info,source)->decoder.setAllocator(android.graphics.ImageDecoder.ALLOCATOR_SOFTWARE));float[] rider;try{Bundle result=new EmbeddingClient(c).run("image",PhotoIndexExecutor.imageInput(bitmap),null,false);require(result.getString("actual_backend").equals("gpu"),"Image backend unverified");rider=result.getFloatArray("output_0");}finally{bitmap.recycle();}String visual=ClipTokenizer.rewrite("自行车");Bundle textResult=new EmbeddingClient(c).run("text",null,new ClipTokenizer(c).encode(visual),false);require(textResult.getString("actual_backend").equals("gpu"),"Text backend unverified");float[] query=textResult.getFloatArray("output_0");FloatBuffer vectors=ByteBuffer.wrap(Files.readAllBytes(reference.toPath())).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();require(vectors.remaining()==128*512,"Expected 128 independent reference images");String space="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
                try(VectorIndex index=new VectorIndex(c,space)){try{for(int id=1;id<=128;id++){float[] vector=new float[512];vectors.get(vector);index.put(id,vector);}index.put(129,rider);JSONArray hits=index.nearest(query,50);int rank=0;for(int i=0;i<hits.length();i++)if(hits.getJSONObject(i).getLong("id")==129)rank=i+1;JSONObject report=new JSONObject().put("images",129).put("query","自行车").put("visual_query",visual).put("rider_rank",rank).put("gpu",true).put("real_sqlite_vec",true).put("source",fixture);Files.writeString(new File(c.getFilesDir(),"rider-retrieval.json").toPath(),report.toString(2));require(rank>0&&rank<=50,"Rider not in top fifty: "+rank);}finally{for(int id=1;id<=129;id++)index.remove(id);}}
            });
            for(String role:new String[]{"image","text","face"})check("gpu_requested_probe_"+role,()->{
                File root=new File(c.getFilesDir(),"search-models");float[] input=null;int[] tokens=null;
                if(role.equals("text"))tokens=new ClipTokenizer(c).encode("a photo of a bicycle");
                else if(role.equals("image")){byte[] bytes=Files.readAllBytes(new File(root,"image-input.bin").toPath());FloatBuffer buffer=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();input=new float[buffer.remaining()];buffer.get(input);}else{FloatBuffer buffer=ByteBuffer.wrap(Files.readAllBytes(new File(root,"face-input.bin").toPath())).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();input=new float[buffer.remaining()];buffer.get(input);}
                Bundle result=new EmbeddingClient(c).run(role,input,tokens,true);float[] vector=result.getFloatArray("output_0");require(vector!=null&&vector.length>0,"GPU output");
                if(!role.equals("face")){byte[] bytes=Files.readAllBytes(new File(root,role+"-reference.bin").toPath());FloatBuffer ref=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer();double dot=0,a=0,b=0;for(float value:vector){float expected=ref.get();dot+=value*expected;a+=value*value;b+=expected*expected;}require(dot/Math.sqrt(a*b)>.99,"GPU reference cosine");}
                if(role.equals("face")){float[] other=result.getFloatArray("output_1");JSONArray faces=FaceDecoder.decode(vector.length>other.length?vector:other,vector.length>other.length?other:vector,820,1024);require(faces.length()>0,"Portrait face not detected");}
                android.util.Log.i("AIOSSearchAcceptance","GPU probe "+role+" output="+vector.length+" elapsed_us="+result.getLong("elapsed_us")+" backend="+result.getString("actual_backend"));
            });
        }
        }
        if(options!=null&&options.getString("inventory","false").equals("true"))check("completed_album_vector_snapshot_integrity",()->{
            try(PhotoIndexStore store=new PhotoIndexStore(c)){JSONObject progress=store.progress(),active=store.activeGeneration();require(store.coverageComplete()&&active!=null,"Album inventory incomplete");int expected=Integer.parseInt(options.getString("expected_photos","5000"));require(progress.getInt("discovered")==expected,"Unexpected inventory count");long generation=active.getLong("id");String space=active.getString("space_id");try(VectorIndex index=new VectorIndex(c,space,generation)){require(index.size()==expected&&progress.getInt("indexed")==expected,"Vector count mismatch");try(android.database.Cursor cursor=store.getReadableDatabase().rawQuery("SELECT count(*) FROM photos p JOIN photo_snapshots s ON s.id=p.id AND s.generation=? WHERE p.visible=1 AND s.visible=1 AND p.source_version=s.source_version AND p.embedding_state=s.embedding_state AND p.face_state=s.face_state AND p.exif_state=s.exif_state",new String[]{Long.toString(generation)})){cursor.moveToFirst();require(cursor.getInt(0)==expected,"Snapshot state mismatch");}
                float[] query=new float[512];query[0]=1;double[] elapsed=new double[40];for(int i=0;i<elapsed.length;i++){long t=System.nanoTime();require(index.nearest(query,20).length()==20,"KNN budget mismatch");elapsed[i]=(System.nanoTime()-t)/1000000d;}java.util.Arrays.sort(elapsed);File database=new File(c.getFilesDir(),"photo-vectors/"+space+(generation==0?"":"-"+generation)+".db");JSONObject stats=new JSONObject().put("photos",expected).put("vectors",index.size()).put("snapshots_match",true).put("database_bytes",database.length()).put("wal_bytes",new File(database.getPath()+"-wal").length()).put("knn_p50_ms",elapsed[19]).put("knn_p95_ms",elapsed[37]).put("space_id",space).put("generation",generation);Files.writeString(new File(c.getFilesDir(),"production-index-integrity.json").toPath(),stats.toString(2));}
            }
        });
        try{JSONObject report=new JSONObject().put("passed",passed).put("failed",failed).put("checks",checks);File f=new File(c.getFilesDir(),"search-acceptance.json");Files.writeString(f.toPath(),report.toString(2));Bundle result=new Bundle();result.putString("report",report.toString());finish(failed==0?ActivityResult.OK:ActivityResult.FAIL,result);}catch(Exception e){finish(1,new Bundle());}
    }
    private static final class ActivityResult{static final int OK=-1,FAIL=1;}
}
